'use client';

import { useState, useEffect, useRef } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import { useRouter } from '@/navigation';
import {
    Save, ArrowLeft, Plus, Move, Trash2, Layout, Type,
    Image as ImageIcon, Copy, MousePointer2, X,
    Bold, Italic, Underline, AlignLeft, AlignCenter, AlignRight, Palette,
    Type as TypeIcon, Minus, Plus as PlusIcon, PaintBucket, Settings,
    Eye, EyeOff, Monitor, Laptop, Smartphone
} from 'lucide-react';
import { getLocalizedName } from '@/app/utils/locale';
import toast from 'react-hot-toast';

interface Snippet {
    id: string;
    name: string;
    category: string;
    htmlContent: string;
    thumbnail?: string;
}

interface Page {
    id: string;
    title: any;
    url: string;
    content: string | null;
}

interface DroppedSnippet {
    id: string; // unique instance id
    snippetId: string;
    htmlContent: string;
    name: string;
}

export default function VisualEditor({ params }: { params: Promise<{ id: string }> }) {
    const t = useTranslations('Admin');
    const commonT = useTranslations('Common');
    const router = useRouter();
    const locale = useLocale();

    const [page, setPage] = useState<Page | null>(null);
    const [snippets, setSnippets] = useState<Snippet[]>([]);
    const [droppedSnippets, setDroppedSnippets] = useState<DroppedSnippet[]>([]);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
    const [editorLocale, setEditorLocale] = useState('en');
    const [previewMode, setPreviewMode] = useState(false);

    // States for the current locale's content
    const [contentEn, setContentEn] = useState<DroppedSnippet[]>([]);
    const [contentAr, setContentAr] = useState<DroppedSnippet[]>([]);

    const [activeElement, setActiveElement] = useState<HTMLElement | null>(null);
    const [activeSnippetId, setActiveSnippetId] = useState<string | null>(null);

    // Selection state for typography
    const [activeStyles, setActiveStyles] = useState({
        fontSize: '16px',
        color: '#000000',
        backgroundColor: 'transparent',
        textAlign: 'left'
    });

    const canvasRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const init = async () => {
            const { id } = await params;
            await Promise.all([fetchPage(id), fetchSnippets()]);
        };
        init();
    }, [params]);

    const fetchPage = async (id: string) => {
        try {
            const res = await fetch(`/api/pages/${id}`);
            if (res.ok) {
                const data = await res.json();
                setPage(data);
                if (data.content) {
                    try {
                        let parsed = data.content;
                        if (typeof parsed === 'string') parsed = JSON.parse(parsed);

                        if (typeof parsed === 'object' && !Array.isArray(parsed)) {
                            const en = parsed.en || [];
                            const ar = parsed.ar || [];
                            setContentEn(en);
                            setContentAr(ar);
                            setDroppedSnippets(editorLocale === 'en' ? en : ar);
                        }
                    } catch (e) { console.log('Content parse error', e); }
                }
            }
        } catch (error) { console.error('Failed to fetch page', error); }
    };

    const fetchSnippets = async () => {
        try {
            const res = await fetch('/api/snippets');
            if (res.ok) {
                const data = await res.json();
                setSnippets(data);
            }
        } catch (error) { console.error('Failed to fetch snippets', error); }
        finally { setLoading(false); }
    };

    const switchLocale = (newLocale: string) => {
        if (newLocale === editorLocale) return;

        if (editorLocale === 'en') {
            setContentEn(droppedSnippets);
            setDroppedSnippets(contentAr);
        } else {
            setContentAr(droppedSnippets);
            setDroppedSnippets(contentEn);
        }

        setEditorLocale(newLocale);
        setActiveElement(null);
        setActiveSnippetId(null);
    };

    const handleDragStart = (e: React.DragEvent, snippet: Snippet) => {
        if (previewMode) return;
        e.dataTransfer.setData('text/plain', JSON.stringify(snippet));
    };

    const handleDragOver = (e: React.DragEvent, index?: number) => {
        if (previewMode) return;
        e.preventDefault();
        setDragOverIndex(index !== undefined ? index : droppedSnippets.length);
    };

    const handleDrop = (e: React.DragEvent) => {
        if (previewMode) return;
        const snippetData = e.dataTransfer.getData('text/plain');
        if (!snippetData) return;
        try {
            const snippet: Snippet = JSON.parse(snippetData);
            const newSnippet: DroppedSnippet = {
                id: crypto.randomUUID(),
                snippetId: snippet.id,
                htmlContent: snippet.htmlContent,
                name: snippet.name
            };
            const dropIndex = dragOverIndex !== null ? dragOverIndex : droppedSnippets.length;
            setDroppedSnippets(prev => {
                const newList = [...prev];
                newList.splice(dropIndex, 0, newSnippet);
                return newList;
            });
        } catch (err) { console.error('Drop failed', err); }
        setDragOverIndex(null);
    };

    const commitChanges = (id: string) => {
        const wrapper = document.getElementById(`snippet-content-${id}`);
        if (wrapper) {
            const clone = wrapper.cloneNode(true) as HTMLElement;
            clone.querySelectorAll('*').forEach(el => {
                const htmlEl = el as HTMLElement;
                htmlEl.style.outline = '';
                htmlEl.style.outlineOffset = '';
                el.removeAttribute('contenteditable');
            });
            setDroppedSnippets(prev => prev.map(s => s.id === id ? { ...s, htmlContent: clone.innerHTML } : s));
        }
    };

    const updateActiveStyles = (el: HTMLElement) => {
        const computed = window.getComputedStyle(el);
        setActiveStyles({
            fontSize: computed.fontSize,
            color: computed.color,
            backgroundColor: computed.backgroundColor,
            textAlign: computed.textAlign
        });
    };

    const handleContentClick = (e: React.MouseEvent, snippetId: string) => {
        if (previewMode) return;
        let target = e.target as HTMLElement;
        const wrapper = document.getElementById(`snippet-content-${snippetId}`);

        const smartTarget = target.closest('p, h1, h2, h3, h4, h5, h6, span, a, li, button, img, section, div:not([id^="snippet-content-"])');
        if (smartTarget && wrapper?.contains(smartTarget)) target = smartTarget as HTMLElement;

        e.stopPropagation();

        if (activeElement && activeElement !== target && activeSnippetId) {
            activeElement.style.outline = '';
            activeElement.style.outlineOffset = '';
            commitChanges(activeSnippetId);
        }

        setActiveElement(target);
        setActiveSnippetId(snippetId);
        updateActiveStyles(target);

        if (target.tagName !== 'IMG' && !target.classList.contains('no-edit')) {
            if (target.contentEditable === 'true') return;

            target.contentEditable = 'true';
            target.style.outline = '2px solid #3b82f6';
            target.style.outlineOffset = '2px';
            target.focus();

            const handleBlur = () => {
                target.contentEditable = 'false';
                target.style.outline = '';
                target.style.outlineOffset = '';
                commitChanges(snippetId);
                target.removeEventListener('blur', handleBlur);
            };
            target.addEventListener('blur', handleBlur);
        } else {
            target.style.outline = '2px solid #3b82f6';
            target.style.outlineOffset = '2px';
        }
    };

    const applyStyle = (command: string, value?: string) => {
        if (!activeElement) return;

        if (command === 'backgroundColor') {
            activeElement.style.backgroundColor = value || '';
            updateActiveStyles(activeElement);
        } else if (command === 'fontSize') {
            activeElement.style.fontSize = value || '';
            updateActiveStyles(activeElement);
        } else if (command === 'textAlign') {
            activeElement.style.textAlign = value || '';
            updateActiveStyles(activeElement);
        } else if (command === 'foreColor') {
            document.execCommand('foreColor', false, value);
            updateActiveStyles(activeElement);
        } else {
            document.execCommand(command, false, value);
        }

        if (activeSnippetId) commitChanges(activeSnippetId);
    };

    const handleSave = async () => {
        if (activeSnippetId) commitChanges(activeSnippetId);
        setSaving(true);
        try {
            const latestEn = editorLocale === 'en' ? droppedSnippets : contentEn;
            const latestAr = editorLocale === 'ar' ? droppedSnippets : contentAr;

            const contentToSave = {
                en: latestEn,
                ar: latestAr
            };

            await fetch(`/api/pages/${page?.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ content: JSON.stringify(contentToSave) })
            });
            toast.success(commonT('saved'), { id: 'save-progress' });
        } catch (error) { toast.error('Save failed'); }
        finally { setSaving(false); }
    };

    const moveSnippet = (index: number, direction: 'up' | 'down') => {
        const newSnippets = [...droppedSnippets];
        const targetIndex = direction === 'up' ? index - 1 : index + 1;
        if (targetIndex >= 0 && targetIndex < newSnippets.length) {
            [newSnippets[index], newSnippets[targetIndex]] = [newSnippets[targetIndex], newSnippets[index]];
            setDroppedSnippets(newSnippets);
        }
    };

    if (loading) return <div className="p-8 text-center text-slate-500">Loading Editor...</div>;

    const swatchColors = [
        '#10B981', '#3B82F6', '#EF4444', '#000000',
        '#6366F1', '#64748B', '#8B5CF6', '#F59E0B',
        '#EC4899', '#14B8A6', '#828282', '#FFFFFF'
    ];

    const bgColors = [
        '#EF4444', '#1E293B', '#F59E0B', '#0EA5E9',
        '#8B5CF6', '#10B981', '#3182CE', '#000000'
    ];

    return (
        <div className="flex flex-col h-screen bg-slate-100 overflow-hidden font-sans">
            {/* Header / Toolbar */}
            <div className="h-14 bg-[#1E293B] flex justify-between items-center px-6 z-50 text-white shadow-xl">
                <div className="flex items-center gap-6">
                    <button onClick={handleSave} disabled={saving} className="bg-[#3B82F6] hover:bg-blue-600 text-white px-6 py-2 rounded-lg text-xs font-bold transition-all shadow-lg flex items-center gap-2">
                        <Save className="w-3.5 h-3.5" /> {saving ? '...' : commonT('saveChanges')}
                    </button>
                    <button
                        onClick={() => setPreviewMode(!previewMode)}
                        className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${previewMode ? 'bg-amber-500 text-white' : 'hover:bg-slate-800'}`}
                    >
                        {previewMode ? <EyeOff className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
                        Preview
                    </button>
                </div>

                <div className="flex items-center gap-6">
                    <div className="flex bg-[#0F172A] p-1 rounded-lg">
                        <button onClick={() => switchLocale('ar')} className={`px-4 py-1 rounded text-[10px] font-bold transition-all ${editorLocale === 'ar' ? 'bg-[#3B82F6] text-white shadow-lg' : 'text-slate-400'}`}>AR</button>
                        <button onClick={() => switchLocale('en')} className={`px-4 py-1 rounded text-[10px] font-bold transition-all ${editorLocale === 'en' ? 'bg-[#3B82F6] text-white shadow-lg' : 'text-slate-400'}`}>EN</button>
                    </div>
                    <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                        <span className="text-xs font-bold text-slate-300">{getLocalizedName(page?.title, locale)}</span>
                        <button onClick={() => router.back()} className="p-2 hover:bg-slate-800 rounded-lg"><ArrowLeft className="w-4 h-4" /></button>
                    </div>
                </div>
            </div>

            <div className="flex flex-1 overflow-hidden relative">
                {/* Left Sidebar - Style Designer */}
                <div className={`w-72 bg-white border-r border-slate-200 overflow-y-auto z-40 flex flex-col transition-all duration-300 ${previewMode ? '-ml-72' : 'ml-0'}`}>
                    <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Style Designer</span>
                        <Settings className="w-3.5 h-3.5 text-indigo-500" />
                    </div>

                    <div className="p-5 space-y-8">
                        {/* Active Element Info */}
                        <div className="bg-slate-50 p-4 rounded-xl border border-dashed border-slate-200">
                            <div className="text-[9px] text-slate-400 font-bold uppercase mb-2 flex items-center justify-center gap-2">
                                <MousePointer2 className="w-3 h-3" /> Active Element
                            </div>
                            <div className="text-center">
                                <span className="bg-white px-3 py-1 rounded-full border border-slate-200 text-xs font-black text-indigo-600 shadow-sm">
                                    {activeElement?.tagName.toLowerCase() || 'none selected'}
                                </span>
                            </div>
                        </div>

                        {/* Typography */}
                        <div className="space-y-4">
                            <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                <TypeIcon className="w-3 h-3" /> Typography
                            </div>

                            <div className="space-y-3">
                                <div className="flex justify-between items-center px-1">
                                    <span className="text-[10px] font-bold text-slate-500 uppercase">Font Size</span>
                                    <span className="text-[11px] font-black text-indigo-600">{activeStyles.fontSize}</span>
                                </div>
                                <input
                                    type="range"
                                    min="8" max="120"
                                    value={parseInt(activeStyles.fontSize)}
                                    onChange={(e) => applyStyle('fontSize', `${e.target.value}px`)}
                                    className="w-full h-1.5 bg-indigo-100 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                                />
                            </div>

                            <div className="grid grid-cols-4 gap-1 p-1 bg-slate-100 rounded-xl">
                                <button onClick={() => applyStyle('textAlign', 'left')} className={`p-2 rounded-lg flex justify-center transition-all ${activeStyles.textAlign.includes('left') ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}><AlignLeft className="w-4 h-4" /></button>
                                <button onClick={() => applyStyle('textAlign', 'center')} className={`p-2 rounded-lg flex justify-center transition-all ${activeStyles.textAlign.includes('center') ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}><AlignCenter className="w-4 h-4" /></button>
                                <button onClick={() => applyStyle('textAlign', 'right')} className={`p-2 rounded-lg flex justify-center transition-all ${activeStyles.textAlign.includes('right') ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}><AlignRight className="w-4 h-4" /></button>
                                <button onClick={() => applyStyle('textAlign', 'justify')} className={`p-2 rounded-lg flex justify-center transition-all ${activeStyles.textAlign.includes('justify') ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-400 hover:text-slate-600'}`}><Layout className="w-4 h-4" /></button>
                            </div>

                            <div className="space-y-3">
                                <span className="text-[10px] font-bold text-slate-500 uppercase px-1">Text Color</span>
                                <div className="grid grid-cols-4 gap-2">
                                    {swatchColors.map(c => (
                                        <button
                                            key={c}
                                            onClick={() => applyStyle('foreColor', c)}
                                            className="w-8 h-8 rounded-full border-2 border-white shadow-md hover:scale-110 transition-transform flex items-center justify-center overflow-hidden"
                                            style={{ backgroundColor: c }}
                                        >
                                            {activeStyles.color.toLowerCase() === c.toLowerCase() && <div className="w-2 h-2 bg-white rounded-full shadow-inner" />}
                                        </button>
                                    ))}
                                    <button onClick={() => { const c = prompt('Hex Color:'); if (c) applyStyle('foreColor', c); }} className="w-8 h-8 rounded-full bg-slate-900 border-2 border-white shadow-md flex items-center justify-center"><Palette className="w-3.5 h-3.5 text-white" /></button>
                                </div>
                            </div>
                        </div>

                        {/* Background */}
                        <div className="space-y-4 pt-4 border-t border-slate-100">
                            <div className="flex items-center justify-between">
                                <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                                    <PaintBucket className="w-3 h-3" /> Background
                                </div>
                                <input type="checkbox" className="w-3.5 h-3.5 rounded border-slate-200 text-indigo-600 focus:ring-indigo-500" />
                            </div>

                            <div className="space-y-3">
                                <span className="text-[10px] font-bold text-slate-500 uppercase px-1">Background Color</span>
                                <div className="grid grid-cols-4 gap-2">
                                    {bgColors.map(c => (
                                        <button
                                            key={c}
                                            onClick={() => applyStyle('backgroundColor', c)}
                                            className="w-8 h-8 rounded-full border-2 border-white shadow-md hover:scale-110 transition-transform"
                                            style={{ backgroundColor: c }}
                                        />
                                    ))}
                                    <button onClick={() => applyStyle('backgroundColor', 'transparent')} className="w-8 h-8 rounded-full bg-white border-2 border-slate-100 shadow-md flex items-center justify-center overflow-hidden relative">
                                        <div className="absolute w-full h-[1px] bg-red-400 rotate-45" />
                                    </button>
                                    <button onClick={() => { const c = prompt('Hex Color:'); if (c) applyStyle('backgroundColor', c); }} className="w-8 h-8 rounded-full bg-slate-900 border-2 border-white shadow-md flex items-center justify-center"><Palette className="w-3.5 h-3.5 text-white" /></button>
                                </div>
                            </div>

                            <div className="space-y-3">
                                <span className="text-[10px] font-bold text-slate-500 uppercase px-1 flex items-center gap-2">
                                    <ImageIcon className="w-3 h-3" /> Background Image
                                </span>
                                <input
                                    type="text"
                                    placeholder="https://image-url.com"
                                    className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold text-slate-600 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
                                    onBlur={(e) => {
                                        if (activeElement) {
                                            activeElement.style.backgroundImage = e.target.value ? `url(${e.target.value})` : 'none';
                                            activeElement.style.backgroundSize = 'cover';
                                            activeElement.style.backgroundPosition = 'center';
                                            commitChanges(activeSnippetId!);
                                        }
                                    }}
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* Main Canvas Area */}
                <div className="flex-1 overflow-hidden flex flex-col items-center p-8 bg-[#E2E8F0]">
                    {/* Viewport Control */}
                    <div className="flex gap-4 mb-4 bg-white p-1 rounded-xl shadow-sm border border-slate-200">
                        <button className="p-2 text-indigo-600 bg-indigo-50 rounded-lg"><Monitor className="w-4 h-4" /></button>
                        <button className="p-2 text-slate-400 hover:text-indigo-600 rounded-lg"><Smartphone className="w-4 h-4" /></button>
                    </div>

                    <div
                        ref={canvasRef}
                        onDragOver={(e) => handleDragOver(e)}
                        onDrop={handleDrop}
                        onClick={() => { setActiveElement(null); setActiveSnippetId(null); }}
                        className={`w-full max-w-5xl bg-white shadow-2xl rounded-2xl overflow-y-auto scroll-smooth transition-all duration-500 relative min-h-[500px] ${previewMode ? 'ring-0' : 'ring-1 ring-slate-300'}`}
                    >
                        <div className="flex flex-col">
                            {droppedSnippets.map((item, index) => (
                                <div
                                    key={item.id}
                                    className={`group relative transition-all duration-300 ${!previewMode && activeSnippetId === item.id ? 'z-30' : 'z-auto'}`}
                                >
                                    {/* Snippet Overlay / Tools */}
                                    {!previewMode && (
                                        <div className="absolute top-4 right-4 hidden group-hover:flex items-center gap-1.5 bg-[#1E293B] text-white px-2 py-1 rounded-xl z-50 shadow-2xl border border-white/10 scale-90 opacity-90 hover:scale-100 hover:opacity-100 transition-all">
                                            <button onClick={() => moveSnippet(index, 'up')} className="p-1.5 hover:bg-slate-700 rounded-lg"><Move className="w-3.5 h-3.5 rotate-180" /></button>
                                            <button onClick={() => moveSnippet(index, 'down')} className="p-1.5 hover:bg-slate-700 rounded-lg"><Move className="w-3.5 h-3.5" /></button>
                                            <div className="w-px h-3 bg-slate-700 mx-0.5" />
                                            <button onClick={() => {
                                                const newList = [...droppedSnippets];
                                                newList.splice(index + 1, 0, { ...item, id: crypto.randomUUID() });
                                                setDroppedSnippets(newList);
                                            }} className="p-1.5 hover:bg-slate-700 rounded-lg"><Copy className="w-3.5 h-3.5" /></button>
                                            <button onClick={() => {
                                                if (confirm('Delete section?')) {
                                                    setDroppedSnippets(prev => prev.filter((_, i) => i !== index));
                                                    if (activeSnippetId === item.id) { setActiveElement(null); setActiveSnippetId(null); }
                                                }
                                            }} className="p-1.5 hover:bg-red-900 rounded-lg text-red-100"><Trash2 className="w-3.5 h-3.5" /></button>
                                        </div>
                                    )}

                                    <div
                                        id={`snippet-content-${item.id}`}
                                        dangerouslySetInnerHTML={{ __html: item.htmlContent }}
                                        onClick={(e) => handleContentClick(e, item.id)}
                                        className={`transition-all duration-300 min-h-[50px] ${!previewMode ? 'hover:outline-2 hover:outline-dashed hover:outline-indigo-300' : ''} ${!previewMode && activeSnippetId === item.id ? 'outline-2 outline outline-indigo-500' : ''}`}
                                    />
                                </div>
                            ))}

                            {/* Drop Zone */}
                            {!previewMode && (
                                <div
                                    onDragOver={(e) => handleDragOver(e, droppedSnippets.length)}
                                    className={`h-40 border-2 border-dashed border-slate-300 m-8 rounded-3xl flex flex-col items-center justify-center transition-all gap-3 ${dragOverIndex === droppedSnippets.length ? 'bg-indigo-50 border-indigo-400 scale-105' : 'bg-white hover:bg-slate-50 hover:border-slate-400'}`}
                                >
                                    <Plus className={`w-10 h-10 ${dragOverIndex === droppedSnippets.length ? 'text-indigo-600' : 'text-slate-200'} transition-all`} />
                                    <span className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Drop New Section Here</span>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Right Sidebar - Snippets Library */}
                <div className={`w-80 bg-white border-l border-slate-200 overflow-y-auto z-40 flex flex-col transition-all duration-300 ${previewMode ? '-mr-80' : 'mr-0'}`}>
                    <div className="p-4 border-b border-slate-100 flex items-center justify-between">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">مكتبة القصاصات</span>
                        <Layout className="w-3.5 h-3.5 text-indigo-500" />
                    </div>

                    <div className="p-4 space-y-3">
                        {snippets.map(s => (
                            <div
                                key={s.id}
                                draggable
                                onDragStart={(e) => handleDragStart(e, s)}
                                className="p-5 bg-white border border-slate-200 rounded-2xl cursor-grab active:cursor-grabbing hover:border-indigo-400 hover:shadow-2xl transition-all group relative overflow-hidden"
                            >
                                <div className="relative z-10">
                                    <div className="text-xs font-black text-slate-800 uppercase tracking-tight group-hover:text-indigo-600 transition-colors">{s.name}</div>
                                    <div className="text-[9px] text-slate-400 mt-1 uppercase font-bold tracking-tighter">{s.category}</div>
                                </div>
                                <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-100 transition-opacity">
                                    <PlusIcon className="w-4 h-4 text-indigo-600" />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}
